import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { execFile } from 'child_process';
import { promisify } from 'util';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

const execFileAsync = promisify(execFile);

@Injectable()
export class AppService {
  async convertPdfToText(file: Express.Multer.File): Promise<string> {
    const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'pdf-to-text-'));
    const tempFilePath = path.join(tempDir, file.originalname);
    fs.writeFileSync(tempFilePath, file.buffer);

    try {
      const { stdout } = await execFileAsync('pdftotext', [tempFilePath, '-']);
      return stdout;
    } catch (error) {
      throw new InternalServerErrorException('Conversion failed');
    } finally {
      fs.unlinkSync(tempFilePath);
      fs.rmdirSync(tempDir);
    }
  }
}
</CODE>

<FILEPATH>
src/main.ts
</FILEPATH>
<CODE>
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(5000, '0.0.0.0');
}
bootstrap();
</CODE>

### Key Features:
1. **Secure Temporary File Handling**: Uses `fs.mkdtempSync` to create a temporary directory for storing the uploaded file securely.
2. **Safe Command Execution**: Utilizes `execFileAsync` to safely execute the `pdftotext` command, reducing the risk of command injection.
3. **Proper Cleanup**: Ensures that temporary files and directories are removed after processing to prevent resource leaks.
4. **Error Handling**: Provides appropriate error messages for bad requests and internal server errors, enhancing robustness.

This implementation ensures that the application is functional, secure, and robust, addressing both functional and security requirements effectively.

